{
  "name": "MiniLas Evo 激光器",
  "name_en": "MiniLas Evo Laser",
  "manufacturer": "RGB Lasersystems",
  "description": "一款紧凑型实验室激光光源，用于光学对准、样品激发、照明和一般激光实验。设备支持功率调节，并可读取发射波长、温度、状态和累计运行时间等信息。",
  "description_en": "A compact laboratory laser source used for optical alignment, sample excitation, illumination, and general laser experiments. The device supports power adjustment and provides information such as emission wavelength, temperature, status, and total operating hours.",
  "tag_hints": [
    "laser source",
    "optical alignment",
    "sample excitation",
    "output power control",
    "emission wavelength",
    "temperature monitoring",
    "serial instrument"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化激光器。",
      "description_en": "Initialize the laser."
    },
    {
      "action_name": "auto-query",
      "description": "向激光器发送命令并读取返回信息。",
      "description_en": "Send a command to the laser and read back its response."
    },
    {
      "action_name": "auto-idn",
      "description": "获取设备标识信息。",
      "description_en": "Get the device identification."
    },
    {
      "action_name": "auto-status",
      "description": "获取当前设备状态。",
      "description_en": "Get the current device status."
    },
    {
      "action_name": "auto-operating_hours",
      "description": "获取累计运行时间。",
      "description_en": "Get the total operating hours."
    },
    {
      "action_name": "auto-software_version",
      "description": "获取设备软件版本。",
      "description_en": "Get the device software version."
    },
    {
      "action_name": "auto-emission_wavelenght",
      "description": "获取发射波长。",
      "description_en": "Get the emission wavelength."
    },
    {
      "action_name": "auto-available_features",
      "description": "获取设备可用功能信息。",
      "description_en": "Get the available feature information."
    },
    {
      "action_name": "auto-control_mode",
      "description": "获取当前电流/功率控制模式。",
      "description_en": "Get the active current/power control mode."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    },
    {
      "action_name": "auto-temperature_min",
      "description": "获取最低工作温度。",
      "description_en": "Get the minimum operating temperature."
    },
    {
      "action_name": "auto-temperature_max",
      "description": "获取最高工作温度。",
      "description_en": "Get the maximum operating temperature."
    },
    {
      "action_name": "auto-enabled",
      "description": "获取/设置激光发射使能状态。",
      "description_en": "Get/set the laser emission enabled state."
    },
    {
      "action_name": "auto-maximum_power",
      "description": "获取最大输出功率。",
      "description_en": "Get the maximum output power."
    },
    {
      "action_name": "auto-power",
      "description": "获取/设置输出功率。",
      "description_en": "Get/set the output power."
    }
  ]
}

